  private readonly inbox=new InboxService(); private readonly outbox=new OutboxService(); private readonly ledger:FinanceLedgerEngine; private readonly protector:SensitiveDataProtector;
  constructor(@Inject(DATABASE_CLIENT) private readonly database:DatabaseClient,@Inject(API_CONFIG) private readonly config:ApiConfig,@Inject(PAYOUT_PROVIDER) private readonly payoutProvider:PayoutProvider){this.ledger=new FinanceLedgerEngine(database.db);this.protector=new SensitiveDataProtector(config.piiEncryptionKey,config.piiHmacKey,config.authHmacKey);}

